import { useRef, useState } from "react";

export function Debouncing({
  delayMs = {{delayMs}},
  placeholderText = "{{placeholderText}}",
  accent = "{{accent}}",
  showDelay = {{showDelay}},
}) {
  const [status, setStatus] = useState("Try typing above \u2014 nothing fires until you pause.");
  const timer = useRef(null);
  const onChange = (e) => {
    var value = e.target.value;
    setStatus("Typing\u2026");
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      setStatus(value ? `Search fired for: \u201C${value}\u201D` : "Try typing above \u2014 nothing fires until you pause.");
    }, delayMs);
  };
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <input type="text" placeholder={placeholderText} onChange={onChange}
        style={{ width: "100%", boxSizing: "border-box", padding: "9px 12px", border: `2px solid ${accent}`, borderRadius: 8, fontSize: 13, marginBottom: 8 }} />
      {showDelay && <p style={{ margin: "0 0 8px", fontSize: 10, color: "#24143099" }}>Fires {delayMs}ms after you stop typing</p>}
      <p role="status" style={{ margin: 0, fontSize: 12, fontWeight: 600, minHeight: 18 }}>{status}</p>
    </div>
  );
}
